// Passo 1: entrada inválida para antes de qualquer recursão.
function fatorial(n) {
  if (typeof n !== 'number' || n < 0 || !Number.isInteger(n)) {
    throw new Error('n precisa ser um inteiro >= 0');
  }

  // Passo 2: caso base — a menor versão do problema, resposta na hora.
  if (n === 0) {
    return 1;
  }

  // Passo 3: passo recursivo — problema menor + resultado da menor.
  return n * fatorial(n - 1);
}

// Passo 4: rastreamento de fatorial(4):
//   fatorial(4) = 4 * fatorial(3)
//   fatorial(3) = 3 * fatorial(2)
//   fatorial(2) = 2 * fatorial(1)
//   fatorial(1) = 1 * fatorial(0)
//   fatorial(0) = 1          <- caso base: a pilha começa a desmontar
//   1 -> 1 -> 2 -> 6 -> 24

// Passo 5: confira.
console.log(fatorial(0)); // 1
console.log(fatorial(4)); // 24
